import numpy as np

def make_input(agent=(), moving=(), reward=(), prev=(), obstacles=None):
    x = np.zeros(500, dtype=np.float32)
    def setc(r, c, ch, val=1.0):
        x[(r * 10 + c) * 5 + ch] = val
    # wall border always in channel 3
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                setc(r, c, 3, 1.0)
    if obstacles:
        for r, c in obstacles:
            setc(r, c, 3, 1.0)
    for r, c in agent:
        setc(r, c, 0, 1.0)
    for r, c in moving:
        setc(r, c, 1, 1.0)
    for r, c in reward:
        setc(r, c, 2, 1.0)
    for r, c in prev:
        setc(r, c, 4, 1.0)
    return x

