import numpy as np

def build(agent, prev_cells, reward_row=1, cars=None, walls=True):
    X = np.zeros((1, 500))
    def s(r, c, ch, v=1.0):
        X[0, (r*10 + c)*5 + ch] = v
    if walls:
        for r in range(10):
            for c in range(10):
                if r in (0, 9) or c in (0, 9):
                    s(r, c, 3)
    if agent:
        s(agent[0], agent[1], 0)
    if reward_row is not None:
        for c in range(1, 9):
            s(reward_row, c, 2)
    for (r, c) in (prev_cells or []):
        s(r, c, 4)
    for (r, c) in (cars or []):
        s(r, c, 1)
    return X

