def idx(r, c, ch):
    return (r * 10 + c) * 5 + ch

def make_input(agent=(8, 4), prev=None, reward_cells=(), walls=True, cars=()):
    x = np.zeros(500)
    if walls:
        for r in range(10):
            for c in range(10):
                if r in (0, 9) or c in (0, 9):
                    x[idx(r, c, 3)] = 1.0
    ar, ac = agent
    x[idx(ar, ac, 0)] = 1.0
    if prev is None:
        prev = (agent,)
    for (r, c) in prev:
        x[idx(r, c, 4)] = 1.0
    for (r, c) in reward_cells:
        x[idx(r, c, 2)] = 1.0
    for (r, c) in cars:
        x[idx(r, c, 1)] = 1.0
    return x

