import numpy as np

def make_input(agent=None, reward=None, moving=None, obstacle=None, prev=None):
    x = np.zeros((1, 500))
    for r in range(10):
        for c in range(10):
            base = (r * 10 + c) * 5
            if r == 0 or r == 9 or c == 0 or c == 9:
                x[0, base + 3] = 1.0
            if agent and (r, c) in agent:
                x[0, base + 0] = 1.0
            if reward and (r, c) in reward:
                x[0, base + 2] = 1.0
            if moving and (r, c) in moving:
                x[0, base + 1] = 1.0
            if obstacle and (r, c) in obstacle:
                x[0, base + 3] = 1.0
            if prev and (r, c) in prev:
                x[0, base + 4] = 1.0
    return x

